    [Fact]
    public void Zone1_Size4_MatchesDav1d()
    {
        byte[] above = [243, 151, 248, 104, 128, 5, 144, 225];
        byte[] left = [105, 254, 217, 18, 170, 149, 135, 30];
        byte[] reference = [151, 248, 104, 128, 248, 104, 128, 5, 104, 128, 5, 144, 128, 5, 144, 225];
        byte[] dst = new byte[4 * 4];
        Av1DirectionalPrediction.Predict(above, left, 58, 4, 3, 0, true, false, true, true, dst);
        Assert.True(dst.AsSpan().SequenceEqual(reference), "D45 zone-1 prediction differs from dav1d.");
    }
